mapper.select:
SELECT id, book_id, chapter_name, chapter_num, word_count, create_time
FROM book_chapter
WHERE id = #{id}

SELECT MAX(chapter_num)
FROM book_chapter
WHERE book_id = #{bookId}

SELECT COALESCE(SUM(word_count), 0)
FROM book_chapter
WHERE book_id = #{bookId}

mapper.update:
UPDATE book_chapter
SET chapter_name = #{chapterName},
    chapter_num = #{chapterNum}
WHERE id = #{id}

UPDATE book_chapter
SET word_count = #{wordCount}
WHERE id = #{id}
